<template>
  <div class="wrapper">
    <div class="menu" :style="{'background-color': `#${color}`}">
      <div class="menu-header">
        <div class="p-fluid p-formgrid p-grid">
          <div class="p-field p-col">
            <Dropdown v-model="type" :options="types" optionLabel="name" placeholder="Select type"/>
          </div>
          <div class="p-field p-col">
            <span class="p-float-label">
              <InputText :class="{'p-invalid': input.length < 1}" id="username" type="text" v-model="input"/>
              <label for="username">Username</label>
            </span>
          </div>
          <div class="p-field p-col">
            <Button @click="getLogs(type, input)" label="Search" icon="pi pi-check" class="p-button-info search-btn" :loading="isLoading" :disabled="input.length < 1"/>
          </div>
        </div>
      </div>
      Menu Color: <ColorPicker defaultColor="#ffffff" v-model="color" /> <Button label="Terminal" icon="pi pi-globe" class="p-button-rounded p-button-danger" @click="toggle" iconPos="right" />
      <div class="menu-body">
        <div id="results"></div>
        <OverlayPanel ref="op">
          <img src="https://i.imgur.com/pir70Nt.gif" style="height: 100px; width: 100%;" alt="">
          <Terminal style="height: 150px;" welcomeMessage="Smarator 3000" prompt="dimnjacar$" class="dark-demo-terminal"/>
          <img src="https://i.imgur.com/pir70Nt.gif" style="height: 100px; width: 100%;" alt="">
        </OverlayPanel>
      </div>
    </div>
  </div>
</template>

<script>
import Button from 'primevue/button';
import InputText from 'primevue/inputtext';
import Dropdown from 'primevue/dropdown';
import {Grid} from "gridjs";
import "gridjs/dist/theme/mermaid.css";
import ColorPicker from 'primevue/colorpicker';
import Terminal from 'primevue/terminal';
import TerminalService from 'primevue/terminalservice';
import OverlayPanel from 'primevue/overlaypanel';


export default {
  name: "logs",
  components: {
    InputText, Dropdown, Button,ColorPicker,Terminal,OverlayPanel
  },
  methods: {
    commandHandler(text) {
      let response;
      let argsIndex = text.indexOf(' ');
      let command = argsIndex !== -1 ? text.substring(0, argsIndex) : text;

      switch(command) {
        case "date":
          response = 'Today is ' + new Date().toDateString();
          break;

        case "domac":
          response = 'Domac is gay!';
          break;

        case "sus":
          response = Math.floor(Math.random() * 100);
          break;

        case "porn":
          response = 'RequestLogsFromServer :)))'
          break;

        default:
          response = "Unknown command: " + command;
      }

      TerminalService.emit('response', response);
    },
    toggle(event) {
      this.$refs.op.toggle(event);
    },
    updateLogs(columns, data) {
      this.columns = columns;
      this.data = data;
      this.grid.updateConfig({
        columns: this.columns,
        data: this.data
      }).forceRender();
    },
    getLogs(type, query) {
      this.isLoading = true;
      setTimeout(() => this.isLoading = false, 1000);
      // eslint-disable-next-line no-undef
      mp.trigger('RequestLogsFromServer', type.id, query);
    }
  },
  data() {
    return {
      terminal: false,
      color: 'ffffff',
      grid: null,
      isLoading: false,
      type: {name: 'Admin', id: 1},
      types: [
        {name: 'Admin', id: 1},
        {name: 'Sessions', id: 2},
        {name: 'Admin Record', id: 3},
      ],
      input: '',
      columns: [],
      data: []
    }
  },
  mounted() {
    this.$nextTick(function () {
      TerminalService.on('command', this.commandHandler);
      this.grid = new Grid({
        columns: this.columns,
        search: true,
        sort: true,
        pagination: {
          limit: 5
        },
        data: this.data,
      }).render(document.getElementById("results"));
    })
  },
  beforeUnmount() {
    TerminalService.off('command', this.commandHandler);
  }
}
</script>

<style scoped lang="scss">
::v-deep(.dark-demo-terminal) {
  border-radius: 10px;
  background-color: #212121;
  color: #ffffff;

  .p-terminal-command {
    color: #80CBC4;
  }

  .p-terminal-prompt {
    color: #FFD54F;
  }

  .p-terminal-response {
    color: #9FA8DA;
  }
}
.wrapper {
  height: 100vh;
  width: 100vw;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #1f1f1f1f;
}

.menu {
  padding: 10px;
  width: 700px;
  border-radius: 10px;
}

.search-btn {
  height: 100%;
}
</style>